"""Playback of frames generated by the unchanged upstream BotMotion/BotRenderer.

Windows adaptation by nanhudev. See assets/bots/provenance.json and the original
Apache-2.0/third-party notices. The clock runs only for visible enabled marks.
"""
import gzip,json,math,time,weakref
from collections import OrderedDict
from pathlib import Path
from PySide6.QtCore import QObject,QTimer,QRectF,QPointF,Qt
from PySide6.QtGui import QImage
from PySide6.QtWidgets import QApplication
from shiboken6 import isValid
from motion import animations_enabled

ASSETS=Path(__file__).parent/'assets/bots'


def activity(data,hovered=False,now=None):
    now=time.time() if now is None else now
    sessions=data.get('local',{}).get('sessions',[])
    def age(row):
        value=row.get('updated')
        return now-value if isinstance(value,(int,float)) and math.isfinite(value) else math.inf
    states={str((row.get('activity') if row.get('state')=='running' else None) or row.get('state','')).lower() for row in sessions if age(row)<1800}
    for value in ('asking','question','plan','compacting','thinking','edit','command','read','limited'):
        if value in states:return value
    if 'running' in states or 'working' in states:return 'working'
    if 'error' in states:return 'failed'
    if hovered:return 'opened'
    if not sessions or all(age(row)>3600 for row in sessions):return 'asleep'
    return 'idle'


class BotLibrary:
    def __init__(self,root=ASSETS):
        self.root=Path(root);self.clips={};self.images={};self.side=64;self.margin=.3;self.cache=OrderedDict();self.pages=OrderedDict();self.loaded=OrderedDict();self.ready=False
        manifest=self.root/'manifest.json.gz'
        if not manifest.exists():return
        try:
            if manifest.stat().st_size>32*1024*1024:raise ValueError('Oversize animation manifest')
            with gzip.open(manifest,'rb') as stream:raw=stream.read(64*1024*1024+1)
            if len(raw)>64*1024*1024:raise ValueError('Oversize animation manifest')
            data=json.loads(raw)
            if data.get('version')!=1:raise ValueError('Unsupported animation pack')
            self.side=data['markSide'];self.margin=data['margin'];self.images=data['images']
            for clip in data['clips']:
                if not clip.get('file') or Path(clip['file']).name!=clip['file']:raise ValueError('Invalid animation clip')
                self.clips[(clip['vendor'],clip['light'],clip['state'])]=clip
            self.ready=bool(self.clips)
        except (OSError,ValueError,KeyError,TypeError):self.clips={};self.images={}
    def clip(self,vendor,light,state):
        vendor='ChatGPT' if vendor=='Codex' else vendor
        meta=self.clips.get((vendor,light,state))
        if not meta:return None
        name=meta['file']
        if name in self.loaded:self.loaded.move_to_end(name);return self.loaded[name]
        try:
            with gzip.open(self.root/name,'rb') as stream:raw=stream.read(2*1024*1024+1)
            if len(raw)>2*1024*1024:raise ValueError('Oversize clip')
            clip=json.loads(raw)
            if clip.get('fps')!=24 or not clip.get('frames'):raise ValueError('Invalid clip')
            self.loaded[name]=clip
            while len(self.loaded)>8:self.loaded.popitem(last=False)
            return clip
        except (OSError,ValueError):return None
    def image(self,key):
        if key in self.cache:self.cache.move_to_end(key);return self.cache[key]
        entry=self.images.get(str(key))
        if not entry:return QImage()
        page=entry['page']
        if not isinstance(page,str) or Path(page).name!=page:return QImage()
        if page not in self.pages:
            self.pages[page]=QImage(str(self.root/page))
            while len(self.pages)>4:self.pages.popitem(last=False)
        self.pages.move_to_end(page)
        image=self.pages[page].copy(*entry['rect'])
        if image.isNull():return image
        self.cache[key]=image
        while len(self.cache)>192:self.cache.popitem(last=False)
        return image

_library=None

def library():
    global _library
    if _library is None:_library=BotLibrary()
    return _library


class BotClock(QObject):
    def __init__(self):
        super().__init__(QApplication.instance());self.followers=weakref.WeakSet()
        self.timer=QTimer(self);self.timer.setSingleShot(True);self.timer.setTimerType(Qt.TimerType.PreciseTimer);self.timer.timeout.connect(self.tick)
    def add(self,player):
        self.followers.add(player)
        if not self.timer.isActive() or self.timer.remainingTime()>16:self.timer.start(0)
    def discard(self,player):
        self.followers.discard(player)
        if not self.followers:self.timer.stop()
    def tick(self):
        now=time.monotonic();due=[]
        for player in tuple(self.followers):
            if not isValid(player.meter) or not player.meter.isVisible() or not player.enabled():self.followers.discard(player);continue
            wait=player.advance(now)
            if wait is not None:due.append(wait)
        if due:self.timer.start(max(8,math.ceil(min(due)*1000)))

_clock=None

def clock():
    global _clock
    if _clock is None or not isValid(_clock):_clock=BotClock()
    return _clock


class BotPlayer:
    def __init__(self,meter):self.meter=meter;self.states={};self.shown={};self.started={};self.fading={}
    def enabled(self):return self.meter.settings.get('bot_logos',True) and animations_enabled() and library().ready
    def sync(self):
        if self.enabled() and self.meter.isVisible():clock().add(self)
        else:self.stop()
    def stop(self):
        if _clock is not None:clock().discard(self)
        self.shown.clear()
    def advance(self,now):
        due=[];changed=False
        for vendor,data in self.meter.group_data.items():
            hovered=vendor==self.meter.client and (self.meter.underMouse() or self.meter.peek.isVisible() or self.meter.panel.isVisible())
            notifications=[row for row in getattr(self.meter,'attention_events',[]) if row['vendor']==vendor]
            state='asking' if any(row['kind']=='permission' for row in notifications) else 'limited' if any(row['kind']=='quota' and row.get('event')=='exhaustion' for row in notifications) else 'done' if notifications else activity(data,hovered)
            key=(state,self.meter.light())
            if self.states.get(vendor)!=key:
                previous=self.shown.get(vendor)
                if previous:self.fading[vendor]=(previous,now)
                self.states[vendor]=key;self.started[vendor]=now
            clip=library().clip(vendor,self.meter.light(),state)
            if not clip:continue
            age=max(0,now-self.started[vendor]);frames=clip['frames'];fps=clip['fps'];index=int(age*fps)
            if index>=len(frames):
                start=48 if state not in ('idle','asleep','done') else 0
                index=start+(index-start)%max(1,len(frames)-start)
            frame=frames[index]
            if self.shown.get(vendor)!=frame:self.shown[vendor]=frame;changed=True
            if state=='asleep' and frame.get('rest') and not hovered:
                # Sleeping source clips rest as logos. Revisit only occasionally.
                due.append(180.)
            elif frame.get('rest') and state=='idle':due.append(1/6)
            else:due.append(1/24)
        if changed:self.meter.update()
        return min(due) if due else None
    def draw_frame(self,p,rect,frame,opacity=1.):
        if frame.get('rest'):return False
        image=library().image(frame['image'])
        if image.isNull():return False
        x,y,rotation,sx,sy,foot=frame['pose'];side=rect.width();extent=image.width()/library().side*side
        p.save();p.setOpacity(p.opacity()*frame.get('opacity',1)*opacity)
        p.translate(rect.center()+QPointF(x*side,(y+foot)*side));p.rotate(rotation);p.scale(sx,sy);p.translate(0,-foot*side)
        p.drawImage(QRectF(-extent/2,-extent/2,extent,extent),image);p.restore();return True
    def draw(self,p,vendor,rect):
        if not self.enabled():return False
        frame=self.shown.get(vendor)
        if frame is None:return False
        fading=self.fading.get(vendor)
        if fading:
            share=min(1,(time.monotonic()-fading[1])/.15)
            if share<1 and not fading[0].get('rest') and not frame.get('rest'):
                self.draw_frame(p,rect,fading[0],1-share);self.draw_frame(p,rect,frame,share);return True
            self.fading.pop(vendor,None)
        return self.draw_frame(p,rect,frame)
